import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"The Daily Bookend","description":"","frontmatter":{"title":"The Daily Bookend","order":7},"headers":[],"relativePath":"about/chapters/07-the-daily-bookend.md","filePath":"about/chapters/07-the-daily-bookend.md"}'),n={name:"about/chapters/07-the-daily-bookend.md"};function s(r,e,l,h,d,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h3 id="_07-the-daily-bookend" tabindex="-1">07.<br>The Daily Bookend <a class="header-anchor" href="#_07-the-daily-bookend" aria-label="Permalink to &quot;07.&lt;br&gt;The Daily Bookend&quot;">​</a></h3><h4 id="daily-rhythm-that-operationalizes-commitment-and-boundaries" tabindex="-1">Daily Rhythm That Operationalizes Commitment and Boundaries <a class="header-anchor" href="#daily-rhythm-that-operationalizes-commitment-and-boundaries" aria-label="Permalink to &quot;Daily Rhythm That Operationalizes Commitment and Boundaries&quot;">​</a></h4><p>It&#39;s hard to lose when projects finish on time. It&#39;s not clients that cause delays in the average project, it&#39;s technical debt. Plainly, that means <em>we could have had a conversation earlier to iron out the creases we&#39;re now seeing, but we didn&#39;t want to</em>. When projects take longer than they should it&#39;s because innumerable small assumptions, unasked questions, and exclusions in communication were all tolerated. If we want to avoid big delays we need to avoid the small ones, or at least manage them.</p><blockquote><p>&quot;Delays in feedback loops can mask important, often critical, system information and system dynamics. Management must be aware of the delays.&quot;</p><p>— <em>Simple_Complexity</em> by William Donaldson</p></blockquote><p>This is why we use the smallest reasonable unit of measurement — a day — to measure progress against our plans for projects:</p><ol><li>We review today&#39;s commitments across all active projects each morning</li><li>We end each day by reviewing the delivery of each commitment for that day, to ourselves, our teammates, and our clients</li></ol><p>What this accomplishes:</p><ul><li>We replace surveillance with trust. By confirming what we can expect <em>today</em>, then measuring the result against the expectation, we create a simple repeating cadence that signals to your team what the standard is. You trust them to get their work done without micromanagement</li><li>We create professional excellence during work hours. When you&#39;re at work we expect 100% and less than that is below our standard</li><li>We separate work from life. When we say <em>go home and enjoy yourself</em>, we mean it. Outside of emergencies, no one will contact you about work out of hours</li><li>We make scaling possible. The approach provides clarity, whether we have one or 20 projects. And if things are hectic with 6 people delivering 12 projects, imagine the stress of doubling both those numbers</li></ul>',8)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
